#!/usr/bin/env python3
"""Diagnose the MPI error by trying to run pw.x directly (no MPI wrapper)."""
import subprocess
import os
import shutil

os.chdir('calculations/000')

# Find pw.x
pw_x = shutil.which('pw.x')
print(f"pw.x found at: {pw_x}")

if pw_x is None:
    # Try common locations
    for p in ['/usr/local/bin/pw.x', '/opt/quantum-espresso/bin/pw.x',
              os.path.expanduser('~/quantum-espresso/bin/pw.x'),
              '/usr/bin/pw.x']:
        if os.path.exists(p):
            pw_x = p
            break

if pw_x is None:
    print("pw.x not found in PATH or common locations")
    # Try to find it in /opt and /usr/local only (avoid scanning /)
    for base in ['/opt', '/usr/local', '/usr']:
        if os.path.exists(base):
            try:
                result = subprocess.run(['find', base, '-name', 'pw.x', '-type', 'f'],
                                       capture_output=True, text=True, timeout=10)
                if result.stdout.strip():
                    print(f"Found in {base}: {result.stdout.strip()}")
            except subprocess.TimeoutExpired:
                pass
else:
    # Try running pw.x directly without MPI
    result = subprocess.run(
        [pw_x, '-in', 'pw.in'],
        capture_output=True, text=True, timeout=120
    )
    print(f"Return code: {result.returncode}")
    print(f"\nSTDOUT (last 50 lines):")
    print('\n'.join(result.stdout.split('\n')[-50:]))
    print(f"\nSTDERR (last 50 lines):")
    print('\n'.join(result.stderr.split('\n')[-50:]))
